    /// <summary>
    /// Form initialize method
    /// </summary>
    void init()
    {
        next init();

        if (element.args().callerName() == menuItemDisplayStr(METExciseRegisterLogementView))
        {
            METExciseRegisterView_Purch metExciseRegisterView_Purch = element.args().record();
            FormDataSource              inventSumLocalFDS = this.formRun().dataSource(FormDataSourceStr(InventOnhandItem,InventSum));
            SysQuery::findOrCreateRange(inventSumLocalFDS.queryBuildDataSource(), fieldNum(InventSum, InventSiteId)).value(queryValue(metExciseRegisterView_Purch.SiteId));
        }
    }

    /// <summary>
    /// get METReqItemTable record
    /// </summary>
    /// <param name = "_inventSum">InventSum</param>
    /// <returns>METReqItemTable</returns>
    Public METReqItemTable getReqItemTable(InventSum _inventSum, FormDataSource _inventDim_ds)
    {
        ReqItemTable            reqItemTable;
        METReqItemTable         metReqItemTable;
        InventSum               inventSumLoc;
        InventDim               inventDim,currentInventDim, metInventDim;
        Qty                     salesQty;
        Common                  inventDimJoined = formJoinedRecord(_inventSum, _inventDim_ds);

        currentInventDim = inventDimJoined;

        select firstonly inventSumLoc
            where inventSumLoc.ItemId == _inventSum.ItemId
             join firstonly inventDim 
                where inventDim.inventDimId == inventSumLoc.InventDimId
                  && inventDim.InventSiteId == currentInventDim.InventSiteId
                  && inventDim.InventLocationId == currentInventDim.InventLocationId;

        select firstonly reqItemTable
            where reqItemTable.ItemId == _inventSum.ItemId
            join metReqItemTable
                where metReqItemTable.RefRecId == reqItemTable.RecId
            join metInventDim 
                where metInventDim.inventDimId == reqItemTable.CovInventDimId
                    && metInventDim.InventSiteId == inventDim.InventSiteId
                    && metInventDim.InventLocationId == inventDim.InventLocationId;

        return metReqItemTable;
    
    }

