    Public InventItemSalesSetup getInventItemSales(InventSum _inventSum, FormDataSource _inventDim_ds)
    {
        InventItemSalesSetup    inventItemSalesSetup;
        InventSum               inventSumLoc;
        InventDim               inventDim,currentInventDim;
        Qty                     salesQty;
        Common                  inventDimJoined = formJoinedRecord(_inventSum, _inventDim_ds);

        currentInventDim = inventDimJoined;

        select firstonly inventSumLoc
            where inventSumLoc.ItemId == _inventSum.ItemId
             join firstonly inventDim
                where inventDim.inventDimId == inventSumLoc.InventDimId
                  && inventDim.InventSiteId == currentInventDim.InventSiteId
                  && inventDim.InventLocationId == currentInventDim.InventLocationId;

        select firstonly inventItemSalesSetup
            where inventItemSalesSetup.ItemId == _inventSum.ItemId
                join firstonly inventDim
                where inventDim.inventDimId == inventItemSalesSetup.InventDimId
                  && inventDim.InventSiteId == inventDim.InventSiteId
                  && inventDim.InventLocationId == inventDim.InventLocationId;


        return inventItemSalesSetup;
    
    }

